import { Link, useNavigate } from 'react-router-dom';
import Header from '../components/Header';
import Footer from '../components/Footer';

const Dashboard = () => {
    const session = localStorage.getItem('session');
    const navigate = useNavigate();
    let userData;
    if (!session) {
        navigate('/');
    }
    else {
        userData = JSON.parse(session);
    }
    return (
        <div className="min-h-screen flex flex-col font-body-md text-body-md text-on-surface bg-surface dark:bg-surface-dim">
            <Header />
            <main className="flex-grow flex items-center justify-center px-margin-mobile py-24">
                <div className="w-full max-w-[440px] flex flex-col gap-8">
                    {/* Login Card */}
                    <div className="bg-surface-container-lowest border border-outline-variant rounded-lg p-8 md:p-10 shadow-sm">
                        <div className="text-center mb-10">
                            <h1 className="font-headline-lg text-headline-lg text-primary mb-2">Hey <span className='text-primary-fixed font-bold'> {userData.first_name} {userData.last_name} </span> this is the dashboard.</h1>
                        </div>
                    </div>
                </div>
            </main>
            <Footer />
        </div>
    );
};

export default Dashboard;
